INSERT OR REPLACE INTO station_entrances VALUES ('ENT-127-01', '127', '7 Av', 'W 42 St', 'SE', 'STAIRS', 1, 'Street stair on the block corner beneath the large illuminated advertising screens.', 'This complex has entrances on all four corners feeding different lines. Crossing to a different corner underground means a long passage.', 40.75529, -73.98713, 'SAMPLE_UNVERIFIED', NULL);
INSERT OR REPLACE INTO station_entrances VALUES ('ENT-611-01', '611', 'E 42 St', 'Lexington Av', 'NW', 'STAIRS', 1, 'Stair down directly beside the terminal building frontage.', 'Entering through the main terminal concourse instead adds a long indoor walk before you reach any turnstile.', 40.75182, -73.97663, 'SAMPLE_UNVERIFIED', NULL);
INSERT OR REPLACE INTO station_entrances VALUES ('ENT-A32-01', 'A32', 'W 34 St', '8 Av', 'NE', 'STAIRS', 1, 'Stair at the base of the block-long stone building with the colonnade.', 'The 8 Av station and the 7 Av station are different stations two long blocks apart. Confirm which one your train uses before descending.', 40.75217, -73.99338, 'SAMPLE_UNVERIFIED', NULL);
INSERT OR REPLACE INTO station_entrances VALUES ('ENT-R16-01', 'R16', 'Broadway', 'W 42 St', 'NE', 'STAIRS', 1, 'Stair at the foot of the wide red stepped seating area.', NULL, 40.75529, -73.98663, 'SAMPLE_UNVERIFIED', NULL);
INSERT OR REPLACE INTO station_entrances VALUES ('ENT-635-01', '635', 'E 14 St', 'Union Sq East', 'NE', 'STAIRS', 1, 'Stair at the park-side edge of the plaza, beside the open market area.', 'The south end entrances feed a different mezzanine and require a long walk back underground.', 40.73476, -73.98956, 'SAMPLE_UNVERIFIED', NULL);
INSERT OR REPLACE INTO platform_connections VALUES ('PC-127-7-QUEENS', '127', '7', 'QUEENS', 'From the platform, walk to the far end and take the passage marked for the 7, then ride the long escalator down two levels.', '["7 Flushing","Queens"]', 'The shuttle to Grand Central leaves from a different level; do not follow the S signs.', 'SAMPLE_UNVERIFIED', NULL);
INSERT OR REPLACE INTO platform_connections VALUES ('PC-611-7-QUEENS', '611', '7', 'QUEENS', 'Follow the overhead signs for the 7 down the ramp, then take the escalator to the deepest level.', '["7 Flushing","Queens"]', NULL, 'SAMPLE_UNVERIFIED', NULL);
INSERT OR REPLACE INTO platform_connections VALUES ('PC-635-L-BROOKLYN', '635', 'L', 'BROOKLYN', 'Take the stairs down at the north end of the mezzanine and follow the passage under the street.', '["L Brooklyn","8 Av / Canarsie"]', 'Trains on the level above are the N Q R W; ignore them.', 'SAMPLE_UNVERIFIED', NULL);
INSERT OR REPLACE INTO exit_car_alignments VALUES ('EXIT-127-611-S', '127', '611', 'S', 1, 'Board at the very front of the shuttle.', 'Front-of-platform stair', 'Lexington Av at E 42 St', 'SAMPLE_UNVERIFIED', NULL);
INSERT OR REPLACE INTO exit_car_alignments VALUES ('EXIT-635-127-N', '635', '127', 'N', 8, 'Stand toward the rear half of the platform.', 'Rear stair to the 42 St mezzanine', 'Broadway at W 42 St', 'SAMPLE_UNVERIFIED', NULL);
COMMIT;
